/**
 * AI providers: org-owned reference identities, name-keyed lookups — never
 * authored/created (they hold credentials, manually configured on the
 * platform; src/CLAUDE.md), only referenced. One kind per AiProviderType
 * (Anthropic, Bedrock, ..., matching the 10 distinct `elementum_<type>_
 * ai_provider` terraform data sources) sharing the single "aiProviders" org
 * bag — `pull org`/`catalog/org.ts` treat that bag's entries uniformly
 * regardless of which of the 10 kinds produced them.
 */
import { NO_CATALOG, NO_LIFECYCLE } from "../../graph/types.js";
/** org.ts / OrgRefLookup bag — keep in lockstep with `data.orgBag`. */
export const AI_PROVIDER_ORG_BAG = "aiProviders";
const AI_PROVIDER_TYPES = [
    { kind: "ai-provider-anthropic", resourceType: "elementum_anthropic_ai_provider", label: "Anthropic" },
    { kind: "ai-provider-bedrock", resourceType: "elementum_bedrock_ai_provider", label: "Bedrock" },
    { kind: "ai-provider-custom", resourceType: "elementum_custom_ai_provider", label: "Custom" },
    { kind: "ai-provider-deepgram", resourceType: "elementum_deepgram_ai_provider", label: "Deepgram" },
    { kind: "ai-provider-elevenlab", resourceType: "elementum_elevenlab_ai_provider", label: "ElevenLab" },
    { kind: "ai-provider-gemini", resourceType: "elementum_gemini_ai_provider", label: "Gemini" },
    { kind: "ai-provider-openai", resourceType: "elementum_openai_ai_provider", label: "OpenAI" },
    { kind: "ai-provider-snowflake", resourceType: "elementum_snowflake_ai_provider", label: "Snowflake" },
    { kind: "ai-provider-xai", resourceType: "elementum_xai_ai_provider", label: "xAI" },
    { kind: "ai-provider-managed", resourceType: "elementum_managed_ai_provider", label: "Elementum Managed" },
];
export const aiProviderModules = AI_PROVIDER_TYPES.map(({ kind, resourceType, label }) => ({
    kind,
    stream: { role: "orgExport" },
    data: {
        participates: true,
        lookupAttr: "name",
        catalogKind: "aiProvider",
        orgBag: AI_PROVIDER_ORG_BAG,
        // Connectors reference their provider (`provider_id`), so build emits
        // this data source and the build-vs-export scopes it.
        referencedByBuild: true,
    },
    authoring: { unit: "none" },
    parents: [{ parent: "org", child: kind }],
    resource: { shape: "single", resourceType, adoptable: false },
    lifecycle: NO_LIFECYCLE,
    canvas: { participates: true, label: `AI Providers (${label})`, glyph: "◆", component: "orgIdentity" },
    // Rendered specially in src/catalog/org.ts (nested with each provider's
    // connectors under `aiProviders.<provider>.models.<model>`), not through
    // the generic per-bag catalog renderer.
    catalog: NO_CATALOG,
}));
